    perform(effectsChainCopy);perform(effectsOpen,1);perform(effectsChainPaste);check(project.tracks[7].mixer.dynamics==project.masterMixer.dynamics,"effect-chain clipboard retains complete dynamics when copied from Master to channel");project.tracks[5].isBus=true;selectedTrack=5;perform(effectsOpen,1);check(applyDynamicsMode(DynamicsMode::expander,5,revision)&&project.tracks[5].mixer.dynamics.mode==DynamicsMode::expander,"mixer buses support an independent expander mode");
