void Studio::runDynamicsTransportTick(){
    auto put=[&](const char* name,bool value){transportResults.getDynamicObject()->setProperty(name,value);};auto accept=[&](const String& value,int result=1){if(auto* d=dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent())){d->getTextEditor("value")->setText(value);d->exitModalState(result);}};
    if(transportTicks==5000){perform(stop);cancelNoteTool(false);project=emptyProject();project.master=1;project.loop=true;project.patterns[0].length=4;selectedTrack=7;selectedNote=-1;selectedNotes.clear();currentFile={};lane()={{0,3,60,1}};project.tracks[7].volume=1.5f;project.tracks[7].send=0;undoStack.clear();redoStack.clear();publish();perform(masterInsertsOpen,1);put("nativeDynamicsMode",applyDynamicsMode(DynamicsMode::limiter,-1,revision));perform(effectToggle,1);editDynamicsValue(compThreshold,-1);put("nativeDynamicsDialog",dynamic_cast<AlertWindow*>(Component::getCurrentlyModalComponent())!=nullptr);accept("-24");}
    if(transportTicks==5010){put("nativeDynamicsTyped",project.masterMixer.threshold==-24&&project.masterMixer.compressor&&project.tracks[7].mixer.threshold==-18);perform(undoAction);bool undo=project.masterMixer.threshold==-18;perform(redoAction);put("nativeDynamicsHistory",undo&&project.masterMixer.threshold==-24);engine->observedPeak.store(0);perform(play);}
    // Drain callbacks from the previous publication before measuring the limiter ceiling.
    if(transportTicks==5015)engine->observedPeak.store(0);
    if(transportTicks==5025){float peak=engine->observedPeak.load();transportResults.getDynamicObject()->setProperty("nativeDynamicsMeasuredPeak",peak);put("nativeDynamicsLimiterAudio",engine->playing.load()&&peak>.001f&&peak<=Decibels::decibelsToGain(-24.f)+.000001f);perform(stop);applyDynamicsMode(DynamicsMode::gate,-1,revision);editDynamicsValue(dynamicsRange,-1);accept("72");}
    if(transportTicks==5035){editDynamicsValue(dynamicsHysteresis,-1);accept("4");}
    if(transportTicks==5040){editDynamicsValue(dynamicsHold,-1);accept("125");}
    if(transportTicks==5050){const auto& d=project.masterMixer.dynamics;put("nativeDynamicsGateValues",d.range==72&&d.hysteresis==4&&d.hold==125);applyDynamicsMode(DynamicsMode::expander,-1,revision);editDynamicsValue(compRatio,-1);accept("2.5");}
    if(transportTicks==5060){put("nativeDynamicsExpander",project.masterMixer.dynamics.mode==DynamicsMode::expander&&project.masterMixer.ratio==2.5f);applyDynamicsMode(DynamicsMode::compressor,-1,revision);editDynamicsValue(dynamicsKnee,-1);accept("6");}
    if(transportTicks==5070){put("nativeDynamicsKnee",project.masterMixer.dynamics.knee==6);editDynamicsValue(dynamicsHold,-1);perform(effectsOpen,1);accept("500");}
    if(transportTicks==5075){put("nativeDynamicsStale",project.masterMixer.dynamics.hold==125&&status.startsWith("Dynamics target changed"));perform(masterInsertsOpen,1);editDynamicsValue(compThreshold,-1);accept("NaN");}
    if(transportTicks==5080){put("nativeDynamicsInvalid",project.masterMixer.threshold==-24&&status.startsWith("Enter a finite"));editDynamicsValue(compThreshold,-1);accept("-1",0);}
    if(transportTicks==5085){put("nativeDynamicsCancel",project.masterMixer.threshold==-24);editDynamicsValue(dynamicsKnee,-1);engine->beginTake({0,0,-1,0});recording=true;accept("12");}
    if(transportTicks==5090){recording=false;put("nativeDynamicsRecording",project.masterMixer.dynamics.knee==6&&status.startsWith("Dynamics target changed"));perform(stop);auto file=transportReport.getSiblingFile("native-dynamics.pulse");Project read;put("nativeDynamicsSave",saveProject(project,file).wasOk()&&loadProject(file,read).wasOk()&&read.masterMixer.dynamics==project.masterMixer.dynamics);}
    if(transportTicks==5095){engine->observedPeak.store(0);transportFrames=engine->processedFrames.load();}
    if(transportTicks==5105)put("nativeDynamicsStop",!engine->playing.load()&&engine->observedPeak.load()==0&&engine->processedFrames.load()>transportFrames);
}
